paragraph.math:
$$\begin{array}{l}
  {{f^{\prime}(x)}{= \frac{d}{\mathit{dx}}\left( {x\ln x} \right) = x\frac{d}{\mathit{dx}}\left( {\ln x} \right) + \left( {\ln x} \right)\frac{d}{\mathit{dx}}(x)}} \\
  {\phantom{f^{\prime}(x)}{= x\left( \frac{1}{x} \right) + \ln x = 1 + \ln x}}
  \end{array}$$

$$\begin{array}{l}
  {{g(t)}{= \ln{({t^{2}e^{- t^{2}}})}}} \\
  {\phantom{g(t)}{= \ln t^{2} + \ln e^{- t^{2}}}\qquad{\ln mn = \ln m + \ln n}} \\
  {\phantom{g(t)}{= 2\ln t - t^{2}}\qquad{\ln m^{n} = n\ln m\text{and}\ln e = 1}}
  \end{array}$$

$$\begin{array}{l}
  {{\frac{d}{\mathit{dx}}\ln y}{= \frac{d}{\mathit{dx}}\ln\left\lbrack {f(x)} \right\rbrack}\qquad{\text{Write}y = f(x).}} \\
  {\phantom{\frac{d}{\mathit{dx}}\ln y}{= \frac{f^{\prime}(x)}{f(x)}}\qquad{\text{Use Rule}4.}} \\
  {\phantom{\frac{d}{\mathit{dx}}\ln y}{= \frac{y^{\prime}}{y}}\qquad{\text{Return to using}y\text{instead of}f(x).}}
  \end{array}$$
